from lib import *
S = SS('p48')
steps = [
    step("看起来像空格的字符,Python 的 strip()、split()、正则 \\s 对它们的处理一致:普通空格、制表符、换行、不间断空格 nbsp(U+00A0)、全角空格(U+3000)、细空格(U+2009)、窄不间断空格(U+202F)——全是空白(isspace 为 True),三种方式都当作空白。但零宽空格 U+200B、零宽不连字 U+200C、零宽连字 U+200D、BOM/零宽不换行 U+FEFF、软连字符 U+00AD、左到右标记 U+200E、单词连接符 U+2060——类别是 Cf,isspace 为 False,strip、split、\\s 都不当空白。例:'Price:\\xa0¥100\\u200b \\u3000 ok\\ufeff'.split() 得到 ['Price:', '¥100\\u200b', 'ok\\ufeff'],零宽空格和 BOM 留在结果里,看不见但存在。", t=tl(S(1)), done=lidx(S(1), 'nbsp', '全角空格', '细空格'), mark=lidx(S(1), '零宽空格', 'U+FEFF', '软连字符', '例:'), b=bars([['被 strip/split/\\s 当空白的字符', 7, '7'], ['不被当空白的 Cf 字符', 7, '7']], 7, done=[0], mark=[1]), kv=KV([['nbsp、全角空格、细空格', '都是空白,strip/split 能处理'], ['零宽空格、BOM、软连字符', '不是空白,留在文本里'], ['后果', '字符串比较、去重、正则会莫名失败']], ['零宽空格、BOM、软连字符'])),
    step("NFKC 规范化把全角变成半角:'１２３ＡＢＣ，．' → '123ABC,.';'ｱｲｳ（ﾊﾝｶｸ）' → 'アイウ(ハンカク)';'１２，３４５．６７円' → '12,345.67円'。但它的副作用不小:'x²+y³' → 'x2+y3'(数学含义变了)、'①②③' → '123'、'ﬁle ﬂow' → 'file flow'、'™' → 'TM'、'…' → '...'、'～' → '~'、'㈱' → '(株)'。中文标点:，！？：；（）被转成半角的 , ! ? : ; ( ),而 。【】、 保持不变。引号 “” 和破折号 —— 不变。不要无脑对全文做 NFKC。", t=tl(S(2)), done=lidx(S(2), '１２３ＡＢＣ', 'ｱｲｳ', '１２，３４５'), mark=lidx(S(2), 'x²+y³', '①②③', 'ﬁle', '™'), kv=KV([['全角数字、字母、逗号', 'NFKC 后变半角'], ['上标 ²、圈数字 ①、连字 ﬁ、™', '含义被改变'], ['中文标点', '部分变半角,部分不变']], ['上标 ²、圈数字 ①、连字 ﬁ、™'])),
    step("NFC 与 NFD:'café'(é 是一个字符 U+00E9)和 'cafe\\u0301'(e 加组合重音)显示完全一样,但 == 是 False,长度 4 和 5;规范化成 NFC 后相等。韩文 '한글' 的 NFC 长度 2、NFD 长度 6,同样 == 为 False,NFC 后相等。放进集合去重:{a, b} 大小是 2,规范化后是 1。macOS 的文件名等来源常常给出 NFD。", t=tl(S(3)), done=lidx(S(3), '去重集合', '한글'), mark=lidx(S(3), "café"), b=bars([['原样去重:集合大小', 2, '2'], ['NFC 后去重:集合大小', 1, '1']], 2, mark=[0], done=[1]), kv=KV([['café(NFC)与 café(NFD)', '== 为 False,NFC 后相等'], ['韩文', 'NFC 长 2,NFD 长 6'], ['去重', '不规范化会多出一份']], ['去重'])),
    step("数字解析:Python 的 int() 和 float() 接受 Unicode 数字:int('１２３') = 123、int('١٢٣')(阿拉伯-印度数字)= 123;但 '１２．５'(全角小数点)、'1,234.56'、'１，２３４．５６'、'1 234,56'、'¥100'、'￥100'(全角日元符号)、'１００円'、'12.5万' 全部 ValueError。NFKC 之后 '１２．５' 变成 '12.5'、'￥100' 变成 '¥100'、'１，２３４．５６' 变成 '1,234.56',但逗号和货币符号还要自己去掉;'١٢٣' 在 NFKC 之后仍然是阿拉伯-印度数字(不变)。", t=tl(S(4)), done=lidx(S(4), "'１２３'", "'١٢٣'"), mark=lidx(S(4), "'１２．５'", "'￥100'", "'12.5万'"), kv=KV([['int(全角数字)', '可以,= 123'], ['全角小数点、千分位、货币符号', 'ValueError'], ['NFKC 之后', '数字能转,逗号与符号仍要自己处理']], ['全角小数点、千分位、货币符号'])),
    step("从 HTML 取文本。原始 HTML 里有 &nbsp;、全角价格 ¥１２，３４５、<br>、零宽空格 &#8203;、&emsp;。text_content()、\"\".join(itertext())、xpath string() 三者结果相同,都保留了 \\xa0、\\u200b、\\u2003 和全角字符,并且 <br> 不产生任何分隔('¥１２，３４５half…' 粘在了一起);用 \" \".join(itertext()) 会在每个文本片段之间补空格,把 'a' 'b' 分开但也会多出空白。清洗函数(NFKC → 去零宽/软连字符/方向标记 → 折叠空白):text_content() 得到 'Price: ¥12,345halfwidth アイウ nextline ok ab',join 版本得到 'Price: ¥12,345 halfwidth アイウ nextline ok a b'。不清洗直接用同一个正则 ¥\\s*([\\d,]+),匹配到 '１２'——Python 的 \\d 匹配全角数字,但全角逗号不在 [\\d,] 里,int('１２') = 12,静默得到错误的 12 而不是 12345;清洗后得到 12,345 → 12345。", t=tl(S(5)), done=lidx(S(5), 'clean(', '从清洗后的文本里取价格'), mark=lidx(S(5), 'text_content()', '不清洗直接用同一个正则'), kv=KV([['<br>', '不产生分隔,文字直接粘在一起'], ['不清洗取价格', '得到 12 而不是 12345,静默出错'], ['清洗后', '12,345 → 12345']], ['不清洗取价格'])),
]
A = mkartp('p48', 48, '爬虫,文本清洗,Unicode,NFKC,nbsp,零宽字符,全角半角,Python,真实验证,动画演示',
    '实测爬虫文本清洗:nbsp 和全角空格能被 strip/split/\\s 处理,零宽空格、BOM、软连字符不能;NFKC 能把全角转半角,但也把 x² 变成 x2、① 变成 1;NFC 与 NFD 的 café 显示一样却不相等;不清洗时正则把「¥１２，３４５」读成 12 而不是 12345。',
    '网页文字里藏着一堆看不见或者看起来一样的字符:不间断空格、零宽空格、全角数字和逗号、组合重音。它们让字符串比较、去重和价格解析静默地出错。这篇逐类用 Python 验证,并给出一个清洗函数。',
    [('7 对 7', 'Python 当空白处理的 7 个“空格类”字符(nbsp、全角空格等)与不当空白处理的 7 个 Cf 字符(零宽空格、BOM 等)'), ('12 而不是 12345', '不清洗时,正则 ¥\\s*([\\d,]+) 对「¥１２，３４５」取到的价格'), ('2 对 1', '不规范化与 NFC 之后,「café」两种写法放进集合的大小')],
    [('空白类字符', '<p>不间断空格 nbsp、全角空格 U+3000、细空格都被 <code>str.strip()</code>、<code>str.split()</code>、正则 <code>\\s</code> 当作空白。零宽空格、零宽连字、BOM、软连字符、方向标记属于 Cf 类,<code>isspace()</code> 为 False,留在文本里——比较、去重、关键词匹配会莫名其妙地失败。</p>'),
     ('NFKC 的利弊', '<p>NFKC 把全角数字字母和逗号变成半角(<code>１２，３４５．６７円</code> → <code>12,345.67円</code>),但同时改变含义:<code>x²</code> 变 <code>x2</code>、<code>①</code> 变 <code>1</code>、<code>™</code> 变 <code>TM</code>、<code>…</code> 变 <code>...</code>。只对需要的字段做,不要对全文做。</p>'),
     ('NFC 与 NFD', '<p>带重音的字符可以是一个码点,也可以是“字母加组合符号”;显示一样,<code>==</code> 为 False。去重或比较之前统一成 NFC。</p>'),
     ('数字解析', '<p>Python 的 <code>int()</code> 接受各种 Unicode 数字(全角、阿拉伯-印度),但不接受全角小数点、千分位逗号、货币符号和“万”。NFKC 能转全角,逗号与符号还要自己处理。</p>'),
     ('HTML 取文本与清洗函数', '<p><code>text_content()</code>、<code>itertext()</code>、<code>string()</code> 都保留不间断空格、零宽字符和全角字符,<code>&lt;br&gt;</code> 不产生分隔。清洗函数的步骤:NFKC(只针对要做的字段)、去掉零宽/软连字符/方向标记、把各种空白折叠成一个空格。不清洗时用 <code>\\d</code> 的正则会把全角价格截成 12——这种错误没有任何异常。</p>')],
    steps,
    [ENV_P + '。Python 3.14.8(unicodedata 的 Unicode 版本 16.0.0)标准库 re、unicodedata;lxml 6.1.1 的 text_content、itertext、xpath string();所有结果都是当场运行的字符串操作,不发网络请求;阿拉伯-印度数字等只试了几个样例',
     '没有验证:其它语言或脚本里的特殊空白与组合字符(泰语、阿拉伯语的连字);NFKC 对日文、韩文、中文兼容字符的全部影响(只试了常见样例);emoji 的变体选择符 U+FE0F 与肤色修饰符;双向文本的控制字符;对大文本做规范化的性能;真实站点里这些字符出现的频率'],
    '文本清洗')
